const isItemInEditState = ArasModules.item.isEditState(options.itemTypeName, options.itemId);
if (!isItemInEditState) {
	return { disabled: true };
}

const { hasOriginal = false, isViewOriginalFormMode = false } = window.formEditorLayout?.state ?? {}
const disabled = !hasOriginal || isViewOriginalFormMode;
return { disabled };
